    // and a river. Neither the grid nor the contours warp the dither cells.
    height = 0.10 + 0.67 * contourPeak(land, vec2(-0.53, 0.41), vec2(1.26, 1.53))
                  + 0.51 * contourPeak(land, vec2(0.58, -0.39), vec2(1.66, 2.07))
                  + 0.28 * contourPeak(land, vec2(-0.71, -0.87), vec2(2.02, 1.21))
